  (0 <= nZ)%Z ->
  place_in_model h nZ = Some a ->
  bv_unsigned (Z_to_bv 64 a) = a
  /\ (bv_unsigned (Z_to_bv 64 a) mod page_size = 0)%Z
  /\ (0 < bv_unsigned (Z_to_bv 64 a))%Z
  /\ (bv_unsigned (Z_to_bv 64 a) + nZ <= alloc_top h)%Z
