  (0 < nZ)%Z -> (nZ mod page_size = 0)%Z ->
  (g mod page_size = 0)%Z -> (page_size <= g)%Z ->
  (g + nZ <= alloc_top h)%Z ->
  region_free (vm_reserved h ++ vm_maps h)
    (Z_to_bv 64 g) (Z_to_bv 64 nZ) = true ->
  exists a, place_in_model h nZ = Some a.
